css:
/* V1.0.75: scoped card learning controls */
.deck-controls.surface{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;padding:14px 16px;margin-bottom:16px;box-shadow:none}
.deck-field{display:grid;gap:6px;min-width:0;color:var(--muted);font-size:12px;font-weight:750;line-height:1.4}
.deck-select{position:relative;display:block;min-width:0;color:var(--violet)}
.deck-select::after{content:'';position:absolute;right:15px;top:50%;width:7px;height:7px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;transform:translateY(-70%) rotate(45deg);pointer-events:none}
.deck-select select{display:block;width:100%;min-width:0;max-width:100%;min-height:44px;appearance:none;-webkit-appearance:none;background:var(--soft);color:var(--violet);border:1px solid var(--line);border-radius:12px;padding:10px 32px 10px 12px;font-size:14px;font-weight:700;line-height:1.4;text-overflow:ellipsis;cursor:pointer}
.deck-select select option{background:var(--paper);color:var(--text)}
@media(max-width:480px){.deck-controls.surface{grid-template-columns:minmax(0,1fr);gap:10px;padding:12px 14px}.deck-field{grid-template-columns:64px minmax(0,1fr);align-items:center;gap:10px}.deck-select select{font-size:16px}}
@media(max-width:340px){.deck-field{grid-template-columns:minmax(0,1fr);gap:5px}}
